core_reasoning_1:
\textbf{Claim.}
For the two-dimensional dilute gas of center vortices and antivortices on $\mathbb{R}^2$, define the unnormalised root-of-unity projector
\[
\Delta_N(q):=\sum_{k=1}^{N}\exp\left(\frac{2\pi i kq}{N}\right),\qquad q\in\mathbb{Z}.
\]
If each vortex contributes $V\zeta_v e^{i\theta/N}$ and each antivortex contributes $V\zeta_v e^{-i\theta/N}$, then
\[
Z_{2D}=\sum_{k=1}^{N}\exp\left(2V\zeta_v\cos\frac{\theta+2\pi k}{N}\right),
\qquad
E_k(\theta)=-2\zeta_v\cos\frac{\theta+2\pi k}{N}.
\]

\textbf{Premises.}
\[
\begin{array}{ll}
\text{(P1)} & N\in\mathbb{Z},\ N\ge2,\quad V>0,\quad \zeta_v>0,\quad \theta\in\mathbb{R}.\\[1mm]
\text{(P2)} & n,\bar n\in\mathbb{Z}_{\ge0}\text{ denote vortex and antivortex numbers}.\\[1mm]
\text{(P3)} & \displaystyle w(n,\bar n):=\frac{(V\zeta_v e^{i\theta/N})^n(V\zeta_v e^{-i\theta/N})^{\bar n}}{n!\bar n!}.\\[3mm]
\text{(P4)} & \displaystyle \Delta_N(q):=\sum_{k=1}^{N}\exp\left(\frac{2\pi i kq}{N}\right),\qquad q\in\mathbb{Z}.\\[3mm]
\text{(P5)} & \displaystyle Z_{2D}:=\sum_{n=0}^{\infty}\sum_{\bar n=0}^{\infty}\Delta_N(n-\bar n)w(n,\bar n).\\[3mm]
\text{(P6)} & \displaystyle \sum_{m=0}^{\infty}\frac{x^m}{m!}=e^x\quad\text{for all }x\in\mathbb{C}.\\[2mm]
\text{(P7)} & \displaystyle e^{ia}+e^{-ia}=2\cos a\quad\text{for all }a\in\mathbb{R}.\\[2mm]
\text{(P8)} & \displaystyle Z_k(\theta):=e^{-V E_k(\theta)}\text{ for the }k\text{th branch contribution.}
\end{array}
\]

\textbf{Derivation.}
First, verify the constraint implemented by the unnormalised projector.  Let
\begin{align}
z_q&:=\exp\left(\frac{2\pi iq}{N}\right).
\end{align}
If $q\in N\mathbb{Z}$, then $z_q=1$ and
\begin{align}
\Delta_N(q)&=\sum_{k=1}^{N}1=N
&&\text{by (P4)}.
\end{align}
If $q\notin N\mathbb{Z}$, then $z_q\ne1$ and $z_q^N=1$.  Hence
\begin{align}
(1-z_q)\Delta_N(q)
&=(1-z_q)\sum_{k=1}^{N}z_q^k
&&\text{by (P4)}\\
&=\sum_{k=1}^{N}z_q^k-\sum_{k=1}^{N}z_q^{k+1}\\
&=z_q-z_q^{N+1}\\
&=z_q-z_qz_q^N\\
&=0.
\end{align}
Since $1-z_q\ne0$, it follows that $\Delta_N(q)=0$.  The factor $N$ for $q\in N\mathbb{Z}$ is an overall normalisation of the projected sum and is the convention used here.

Now compute the dilute-gas sum:
\begin{align}
Z_{2D}
&=\sum_{n=0}^{\infty}\sum_{\bar n=0}^{\infty}\Delta_N(n-\bar n)
\frac{(V\zeta_v e^{i\theta/N})^n(V\zeta_v e^{-i\theta/N})^{\bar n}}{n!\bar n!}
&&\text{by (P3)--(P5)}\\
&=\sum_{n=0}^{\infty}\sum_{\bar n=0}^{\infty}\sum_{k=1}^{N}
\exp\left(\frac{2\pi ik}{N}(n-\bar n)\right)
\frac{(V\zeta_v e^{i\theta/N})^n(V\zeta_v e^{-i\theta/N})^{\bar n}}{n!\bar n!}
&&\text{substitute (P4)}\\
&=\sum_{k=1}^{N}
\left[\sum_{n=0}^{\infty}\frac{(V\zeta_v e^{i(\theta+2\pi k)/N})^n}{n!}\right]
\left[\sum_{\bar n=0}^{\infty}\frac{(V\zeta_v e^{-i(\theta+2\pi k)/N})^{\bar n}}{\bar n!}\right]
&&\text{collect powers of }n\text{ and }\bar n\\
&=\sum_{k=1}^{N}
\exp\left(V\zeta_v e^{i(\theta+2\pi k)/N}\right)
\exp\left(V\zeta_v e^{-i(\theta+2\pi k)/N}\right)
&&\text{by (P6)}\\
&=\sum_{k=1}^{N}
\exp\left(V\zeta_v\left[e^{i(\theta+2\pi k)/N}+e^{-i(\theta+2\pi k)/N}\right]\right)
&&\text{combine exponentials}\\
&=\sum_{k=1}^{N}\exp\left(2V\zeta_v\cos\frac{\theta+2\pi k}{N}\right)
&&\text{by (P7)}.
\end{align}
For one branch,
\begin{align}
Z_k(\theta)
&=\exp\left(2V\zeta_v\cos\frac{\theta+2\pi k}{N}\right)
&&\text{the }k\text{th term above}\\
&=\exp\left(-V E_k(\theta)\right)
&&\text{by (P8)}.
\end{align}
Taking logarithms and using $V>0$ gives
\begin{align}
-VE_k(\theta)&=2V\zeta_v\cos\frac{\theta+2\pi k}{N},\\
E_k(\theta)&=-2\zeta_v\cos\frac{\theta+2\pi k}{N}.
\end{align}

\textbf{Final Result.}
\[
\boxed{Z_{2D}=\sum_{k=1}^{N}\exp\left(2V\zeta_v\cos\frac{\theta+2\pi k}{N}\right),\qquad E_k(\theta)=-2\zeta_v\cos\frac{\theta+2\pi k}{N}}
\]
\hfill$\blacksquare$

core_reasoning_2:
\textbf{Claim.}
Let the shift-twisted boundary condition for a dual-photon component on $\mathbb{R}^2\times S^1$ be
\[
\sigma_q(x_3+L_3)=e^{-2\pi iq/N}\sigma_q(x_3),\qquad q=1,\ldots,N-1.
\]
For Fourier modes $\sigma_q(x_3)=A e^{ipx_3}$ with $A\ne0$, the allowed momenta are
\[
p_{m,q}=\frac{2\pi}{L_3}\left(m-\frac{q}{N}\right),\qquad m\in\mathbb{Z},
\]
so there is no zero mode and the smallest nonzero perturbative gap is
\[
\min_{m\in\mathbb{Z},\;1\le q\le N-1}|p_{m,q}|=\frac{2\pi}{NL_3}.
\]

\textbf{Premises.}
\[
\begin{array}{ll}
\text{(P1)} & N\in\mathbb{Z},\ N\ge2,\quad L_3>0.\\[1mm]
\text{(P2)} & \displaystyle q\in\{1,\ldots,N-1\}\text{ labels a nontrivial eigencomponent of the shift action}.\\[1mm]
\text{(P3)} & \displaystyle \sigma_q(x_3+L_3)=e^{-2\pi iq/N}\sigma_q(x_3).\\[2mm]
\text{(P4)} & \displaystyle \sigma_q(x_3)=Ae^{ipx_3},\quad A\ne0,\quad p\in\mathbb{R}.\\[2mm]
\text{(P5)} & \displaystyle e^{ia}=e^{ib}\text{ if and only if }a-b=2\pi m\text{ for some }m\in\mathbb{Z}.\\[2mm]
\text{(P6)} & \displaystyle \text{For }q\in\{1,\ldots,N-1\},\quad \min_{m\in\mathbb{Z}}\left|m-\frac{q}{N}\right|=\frac{\min(q,N-q)}{N}.\\[3mm]
\text{(P7)} & \displaystyle \min_{1\le q\le N-1}\min(q,N-q)=1.
\end{array}
\]

\textbf{Derivation.}
Substitute the Fourier mode into the boundary condition:
\begin{align}
Ae^{ip(x_3+L_3)}
&=e^{-2\pi iq/N}Ae^{ipx_3}
&&\text{by (P3) and (P4)}\\
e^{ipL_3}
&=e^{-2\pi iq/N}
&&\text{divide by }Ae^{ipx_3}\ne0.
\end{align}
Using equality of phases,
\begin{align}
pL_3-\left(-\frac{2\pi q}{N}\right)&=2\pi m
&&\text{by (P5)}\\
pL_3&=2\pi\left(m-\frac{q}{N}\right)
&&\text{rename }m\mapsto -m\\
p_{m,q}&=\frac{2\pi}{L_3}\left(m-\frac{q}{N}\right),\qquad m\in\mathbb{Z}.
\end{align}
A zero mode would require
\begin{align}
0&=\frac{2\pi}{L_3}\left(m-\frac{q}{N}\right),\\
m&=\frac{q}{N}.
\end{align}
But $m\in\mathbb{Z}$ and $0<q/N<1$, so no such $m$ exists.  Therefore the twist eliminates the constant mode.  The smallest allowed magnitude is
\begin{align}
\min_{m,q}|p_{m,q}|
&=\min_{1\le q\le N-1}\frac{2\pi}{L_3}\min_{m\in\mathbb{Z}}\left|m-\frac{q}{N}\right|\\
&=\frac{2\pi}{L_3}\min_{1\le q\le N-1}\frac{\min(q,N-q)}{N}
&&\text{by (P6)}\\
&=\frac{2\pi}{NL_3}
&&\text{by (P7)}.
\end{align}

\textbf{Final Result.}
\[
\boxed{p_{m,q}=\frac{2\pi}{L_3}\left(m-\frac{q}{N}\right),\qquad p_{m,q}\ne0,
\qquad \min_{m,q}|p_{m,q}|=\frac{2\pi}{NL_3}}
\]
\hfill$\blacksquare$

core_reasoning_4:
\textbf{Claim.}
Let an $\vec\alpha_n$ monopole be located at $(x,x_3)=(0,x_*)$ in the shift-twisted $\mathbb{R}^2\times S^1$ setup, with $0<x_*<L_3$.  If
\[
\Psi(x,x_3):=\frac{g^2}{4\pi iL_4}\vec\sigma(x,x_3)
\]
is the image-chain solution
\[
\Psi=-\frac{1}{2}\sum_{l=0}^{N-1}\vec\nu_{n-l}\sum_{k\in\mathbb{Z}}
\left(\frac{1}{\sqrt{|x|^2+(x_{3,l}-NkL_3)^2}}-
\frac{1}{\sqrt{|x|^2+(x_{3,l}-L_3-NkL_3)^2}}\right),
\]
where $x_{3,l}:=x_3-x_*-lL_3$, then the magnetic flux through a constant-$x_3$ plane in the fundamental domain $0\le x_3<L_3$ is
\[
\vec\Phi(x_3)=
\begin{cases}
2\pi\vec\nu_n, & x_*<x_3<L_3,\\
2\pi\vec\nu_{n+1}, & 0\le x_3<x_*.
\end{cases}
\]

\textbf{Premises.}
\[
\begin{array}{ll}
\text{(P1)} & N\in\mathbb{Z},\ N\ge2,\quad L_3>0,\quad 0<x_*<L_3,
\quad 0\le x_3<L_3,\quad x_3\ne x_*.\\[1mm]
\text{(P2)} & \displaystyle \vec\nu_{r+N}=\vec\nu_r\quad\text{for all integer labels }r,
\qquad \sum_{l=0}^{N-1}\vec\nu_{n-l}=0.\\[2mm]
\text{(P3)} & \displaystyle x\in\mathbb{R}^2,\quad r:=|x|,
\quad x_{3,l}:=x_3-x_*-lL_3.\\[2mm]
\text{(P4)} & \displaystyle \Psi(x,x_3):=\frac{g^2}{4\pi iL_4}\vec\sigma(x,x_3)\\
& \displaystyle \quad=-\frac{1}{2}\sum_{l=0}^{N-1}\vec\nu_{n-l}\sum_{k\in\mathbb{Z}}
\left(\frac{1}{\sqrt{r^2+(x_{3,l}-NkL_3)^2}}-
\frac{1}{\sqrt{r^2+(x_{3,l}-L_3-NkL_3)^2}}\right).\\[5mm]
\text{(P5)} & \displaystyle \vec\Phi(x_3):=\int_{\mathbb{R}^2}d^2x\,\partial_{x_3}\Psi(x,x_3).\\[3mm]
\text{(P6)} & \displaystyle \partial_y(r^2+y^2)^{-1/2}=-y(r^2+y^2)^{-3/2}.\\[2mm]
\text{(P7)} & \displaystyle \sum_{k\in\mathbb{Z}}\left[\operatorname{sign}(y-NkL_3)-\operatorname{sign}(y-L_3-NkL_3)\right]\\
& \displaystyle \quad=2\text{ if }y\in(NkL_3,NkL_3+L_3)\text{ for one }k\in\mathbb{Z},\\
& \displaystyle \quad=0\text{ otherwise, with }y\ne NkL_3\text{ and }y\ne L_3+NkL_3.\\[2mm]
\text{(P8)} & \displaystyle \text{The regularisation-dependent interchange term in the sum-integral manipulation is proportional to }\sum_{l=0}^{N-1}\vec\nu_{n-l}.
\end{array}
\]

\textbf{Derivation.}
First derive the plane integral used below.  For $y\ne0$, define
\begin{align}
I(y)&:=\int_{\mathbb{R}^2}d^2x\,\frac{y}{(|x|^2+y^2)^{3/2}}.
\end{align}
Using polar coordinates in $\mathbb{R}^2$,
\begin{align}
I(y)
&=2\pi\int_{0}^{\infty}\frac{\rho y}{(\rho^2+y^2)^{3/2}}\,d\rho\\
&=\pi y\int_{y^2}^{\infty}u^{-3/2}\,du
&&\text{with }u:=\rho^2+y^2,\\ du=2\rho\,d\rho\\
&=\pi y\left[-2u^{-1/2}\right]_{y^2}^{\infty}\\
&=\frac{2\pi y}{\sqrt{y^2}}\\
&=2\pi\operatorname{sign}(y).
\end{align}
The possible extra term from interchanging the infinite image sum and the plane integral vanishes because
\begin{align}
\text{extra term}&=c\sum_{l=0}^{N-1}\vec\nu_{n-l}
&&\text{by (P8)}\\
&=0
&&\text{by (P2)}.
\end{align}
Define
\begin{align}
y_{l,k}^{(0)}&:=x_{3,l}-NkL_3,
&
 y_{l,k}^{(1)}&:=x_{3,l}-L_3-NkL_3.
\end{align}
Differentiate the image-chain solution:
\begin{align}
\partial_{x_3}\Psi
&=-\frac{1}{2}\sum_{l=0}^{N-1}\vec\nu_{n-l}\sum_{k\in\mathbb{Z}}
\partial_{x_3}\left[(r^2+(y_{l,k}^{(0)})^2)^{-1/2}-(r^2+(y_{l,k}^{(1)})^2)^{-1/2}\right]
&&\text{by (P4)}\\
&=-\frac{1}{2}\sum_{l=0}^{N-1}\vec\nu_{n-l}\sum_{k\in\mathbb{Z}}
\left[-\frac{y_{l,k}^{(0)}}{(r^2+(y_{l,k}^{(0)})^2)^{3/2}}+
\frac{y_{l,k}^{(1)}}{(r^2+(y_{l,k}^{(1)})^2)^{3/2}}\right]
&&\text{by (P6)}\\
&=\frac{1}{2}\sum_{l=0}^{N-1}\vec\nu_{n-l}\sum_{k\in\mathbb{Z}}
\left[\frac{y_{l,k}^{(0)}}{(r^2+(y_{l,k}^{(0)})^2)^{3/2}}-
\frac{y_{l,k}^{(1)}}{(r^2+(y_{l,k}^{(1)})^2)^{3/2}}\right].
\end{align}
Now integrate over the plane:
\begin{align}
\vec\Phi(x_3)
&=\int_{\mathbb{R}^2}d^2x\,\partial_{x_3}\Psi
&&\text{by (P5)}\\
&=\frac{1}{2}\sum_{l=0}^{N-1}\vec\nu_{n-l}\sum_{k\in\mathbb{Z}}
\left[2\pi\operatorname{sign}(y_{l,k}^{(0)})-2\pi\operatorname{sign}(y_{l,k}^{(1)})\right]
&&\text{by the derived formula for }I(y)\\
&=\pi\sum_{l=0}^{N-1}\vec\nu_{n-l}\sum_{k\in\mathbb{Z}}
\left[\operatorname{sign}(x_{3,l}-NkL_3)-\operatorname{sign}(x_{3,l}-L_3-NkL_3)\right]
&&\text{substitute }y_{l,k}^{(0)},y_{l,k}^{(1)}.
\end{align}
Let
\begin{align}
A&:=x_3-x_*.
\end{align}
Case 1: $x_*<x_3<L_3$.  Then $0<A<L_3$.  For $l=0$, $x_{3,0}=A\in(0,L_3)$, so
\begin{align}
\sum_{k\in\mathbb{Z}}\left[\operatorname{sign}(x_{3,0}-NkL_3)-\operatorname{sign}(x_{3,0}-L_3-NkL_3)\right]&=2
&&\text{by (P7), }k=0.
\end{align}
For $l=1,\ldots,N-1$, $x_{3,l}/L_3=A/L_3-l\in(-l,1-l)$, which is outside every interval $(Nk,Nk+1)$; hence
\begin{align}
\sum_{k\in\mathbb{Z}}\left[\operatorname{sign}(x_{3,l}-NkL_3)-\operatorname{sign}(x_{3,l}-L_3-NkL_3)\right]&=0
&&\text{by (P7)}.
\end{align}
Therefore
\begin{align}
\vec\Phi(x_3)&=\pi(2\vec\nu_n)+\pi\sum_{l=1}^{N-1}0\cdot\vec\nu_{n-l}\\
&=2\pi\vec\nu_n.
\end{align}
Case 2: $0\le x_3<x_*$.  Then $-L_3<A<0$.  For $l=N-1$,
\begin{align}
\frac{x_{3,N-1}}{L_3}&=\frac{A}{L_3}-(N-1)\in(-N,-N+1),
\end{align}
so $x_{3,N-1}\in(N(-1)L_3,N(-1)L_3+L_3)$ and
\begin{align}
\sum_{k\in\mathbb{Z}}\left[\operatorname{sign}(x_{3,N-1}-NkL_3)-\operatorname{sign}(x_{3,N-1}-L_3-NkL_3)\right]&=2
&&\text{by (P7), }k=-1.
\end{align}
For $l=0,\ldots,N-2$, $x_{3,l}/L_3=A/L_3-l\in(-l-1,-l)$, which is outside every interval $(Nk,Nk+1)$; hence
\begin{align}
\sum_{k\in\mathbb{Z}}\left[\operatorname{sign}(x_{3,l}-NkL_3)-\operatorname{sign}(x_{3,l}-L_3-NkL_3)\right]&=0
&&\text{by (P7)}.
\end{align}
Thus
\begin{align}
\vec\Phi(x_3)
&=\pi(2\vec\nu_{n-(N-1)})\\
&=2\pi\vec\nu_{n+1}
&&\text{by periodicity in (P2)}.
\end{align}
Combining the two cases proves the piecewise flux formula.

\textbf{Final Result.}
\[
\boxed{\vec\Phi(x_3)=
\begin{cases}
2\pi\vec\nu_n, & x_*<x_3<L_3,\\
2\pi\vec\nu_{n+1}, & 0\le x_3<x_*,
\end{cases}}
\]
\hfill$\blacksquare$
